-- Side Quest Life quest catalogue.
--
-- GENERATED by scripts/export-quests-sql.cjs — do not edit by hand. Change the
-- quests in src/constants/quests.ts and questJourneys.ts, then re-run the
-- script, so the app's offline catalogue and the database cannot drift apart.
--
-- Safe to re-run: every row is an upsert. Existing rows keep their created_at
-- so the "newly added first" ordering is not reset by a refresh.
--
-- Requires supabase/quests_created_at.sql to have been run first.

insert into public.quests (
  id, title, short_description, full_description, category_id, timeframe,
  difficulty, estimated_duration_minutes, prompt_for_reflection,
  suggested_proof_type, journey_intro, action_steps, suggested_group
) values
  ('q-w-01', 'Walk 20 minutes without headphones', 'Leave earbuds at home; listen to the street or birds.', 'Pick any outdoor loop or errand route. Walk at least 20 minutes with no podcasts or music. Notice three distinct sounds before you return.', 'cat-nature', 'weekly', 'easy', 25, 'Which sound stuck with you after you stopped?', 'text', 'A short walk with only the world as your soundtrack.', '[{"id":"s1","title":"Leave podcasts and music behind","detail":"Earbuds stay home or stay in your pocket for this walk.","tip":"Choose a quieter stretch or a pocket park—let wind and distant voices be your opening track.","estimateMinutes":1,"interaction":{"kind":"confirm"}},{"id":"s2","title":"Walk at least 20 minutes outside","detail":"Any loop or errand route counts.","tip":"If you can, cut past a patch of green—pause once to watch birds or leaves before naming anything.","estimateMinutes":20,"interaction":{"kind":"timer","minSeconds":1200,"runningHint":"Lock your phone and walk — the timer keeps counting on its own."}},{"id":"s3","title":"Notice three distinct sounds","detail":"Before you finish, name them quietly to yourself.","tip":"When a new sound arrives, stand still one breath—notice distance and texture before you label it.","estimateMinutes":5,"interaction":{"kind":"counter","prompt":"Name the three sounds you noticed on the walk.","count":3,"itemLabel":"sound"}}]'::jsonb, 'outside'),
  ('q-w-02', 'Sit on a bench for 10 minutes', 'Find a public bench; sit and watch people pass.', 'No scrolling. Set a timer for 10 minutes on any park or street bench. Observe movement, light, and weather.', 'cat-relax', 'weekly', 'easy', 15, 'What detail would you not have noticed if you had kept walking?', 'none', 'Ten minutes of stillness in public—no feed, just the scene.', '[{"id":"s1","title":"Find a bench with a view","tip":"Pick a seat where sky or treeline meets buildings—soft horizons calm the eyes faster than walls.","estimateMinutes":5,"interaction":{"kind":"confirm"}},{"id":"s2","title":"Set a 10-minute timer","detail":"No scrolling.","tip":"Start the timer only after the phone is away; one slow exhale helps the switch feel kind.","estimateMinutes":1,"interaction":{"kind":"timer","minSeconds":600,"runningHint":"This is the timer. Phone away now — just sit and watch."}},{"id":"s3","title":"Watch light, people, and weather until the timer ends","tip":"Let your gaze drift like a slow pan—fabric moving, light on skin, clouds reshaping.","estimateMinutes":10,"interaction":{"kind":"input","prompt":"Describe one thing you watched — light, a person, weather.","minChars":20,"placeholder":"A woman fed pigeons while the light turned orange…"}}]'::jsonb, 'do_now'),
  ('q-w-03', 'Cook one meal from scratch', 'No kits: chop vegetables and use the stove yourself.', 'Make one full plate (breakfast, lunch, or dinner) using raw ingredients only—no microwave-only meals. Wash up when done.', 'cat-relax', 'weekly', 'medium', 45, 'Did the process feel slower or more satisfying than usual?', 'photo', 'Cook a real meal with your hands, not a kit.', '[{"id":"s1","title":"Choose raw ingredients only","detail":"Skip microwave-only shortcuts.","tip":"Walk the produce table twice—color often suggests simpler meals than the recipe rabbit hole.","estimateMinutes":5,"interaction":{"kind":"input","prompt":"What are you cooking? List your main raw ingredients.","minChars":15,"placeholder":"Tomato pasta: tomatoes, garlic, basil…"}},{"id":"calendar_reminder","title":"Put it on your calendar","detail":"Choose a date/time and set a reminder so it actually happens.","tip":"Pick a specific slot you will defend like a quiet coffee—vague someday rarely ships.","estimateMinutes":2,"action":{"kind":"calendar"}},{"id":"s2","title":"Chop, heat, and plate one full meal","tip":"Chop in silence for a few minutes—sizzling oil is its own small soundtrack.","estimateMinutes":35,"interaction":{"kind":"photo","prompt":"Plate it, then snap a photo of the finished meal."}},{"id":"s3","title":"Wash up when done","tip":"Rinse with warm water only; treat closing the kitchen as a gentle chapter end, not a sprint.","estimateMinutes":5,"interaction":{"kind":"confirm"}}]'::jsonb, 'low_energy'),
  ('q-w-04', 'Take a bus or train one stop past your usual', 'Ride transit one stop farther, then walk back.', 'Use public transit if available. Get off one stop after your normal stop and walk home or to your destination. If you drive, park 10 minutes farther once.', 'cat-adventure', 'weekly', 'easy', 30, 'What did you see on the extra stretch that you usually skip?', 'text', 'Stretch your route by one stop—see what you usually skip.', '[{"id":"calendar_reminder","title":"Put it on your calendar","detail":"Choose a date/time and set a reminder so it actually happens.","tip":"Pick a specific slot you will defend like a quiet coffee—vague someday rarely ships.","estimateMinutes":2,"action":{"kind":"calendar"}},{"id":"s1","title":"Ride or drive one stop farther","tip":"Take the long curve around a block you usually shortcut—curiosity over efficiency for one leg.","estimateMinutes":15,"interaction":{"kind":"confirm"}},{"id":"s2","title":"Walk the extra stretch mindfully","tip":"Match someone else’s pace for thirty seconds—borrow calm, then return to yours.","estimateMinutes":15,"interaction":{"kind":"timer","minSeconds":600,"runningHint":"Walk it slowly. The timer runs even with the phone locked."}},{"id":"s3","title":"Note one thing you never saw before","tip":"Skip the photo; keep one image in memory first—writing it down seals it better.","estimateMinutes":2,"interaction":{"kind":"input","prompt":"What did you see that you had never noticed before?","minChars":20,"placeholder":"A blue door with a hand-painted number…"}}]'::jsonb, 'outside'),
  ('q-w-05', 'Message someone you have not texted in 30 days', 'Send one genuine check-in—no mass forwards.', 'Choose one person. Write 2–4 sentences asking how they are or referencing something specific you remember about them.', 'cat-social', 'weekly', 'easy', 10, 'How did it feel to reach out without an agenda?', 'none', 'One honest message to someone you have not spoken to lately.', '[{"id":"s1","title":"Pick one person","tip":"Picture their face before typing—warmth hides in specifics, not in length.","estimateMinutes":2,"interaction":{"kind":"input","prompt":"Who is it — and why them, right now?","minChars":10,"placeholder":"Marta — she moved away and I keep thinking of her…"}},{"id":"s2","title":"Write 2–4 genuine sentences","detail":"No mass forwards.","tip":"Mention one ordinary shared detail—weather, food, a street—it bridges distance quietly.","estimateMinutes":5,"interaction":{"kind":"input","prompt":"Draft the message here first — then copy it into your chat.","minChars":40,"placeholder":"Hey, I walked past that bakery we loved and thought of you…"}},{"id":"s3","title":"Send it","tip":"Send before you polish again; sincerity beats perfect wording.","estimateMinutes":1,"interaction":{"kind":"confirm"}}]'::jsonb, 'social'),
  ('q-w-06', 'Identify three plants on your block', 'Use a book or app; write their common names.', 'Walk your block once. Name three plants (trees, weeds, or flowers). If unsure, use a free plant ID app or a field guide from the library.', 'cat-nature', 'weekly', 'medium', 35, 'Did knowing the names change how you looked at the street?', 'text', 'Learn the names of three plants on your block.', '[{"id":"calendar_reminder","title":"Put it on your calendar","detail":"Choose a date/time and set a reminder so it actually happens.","tip":"Pick a specific slot you will defend like a quiet coffee—vague someday rarely ships.","estimateMinutes":2,"action":{"kind":"calendar"}},{"id":"s1","title":"Walk your block once","tip":"Walk the sunny side first—leaves are easier to meet in good light.","estimateMinutes":10,"interaction":{"kind":"timer","minSeconds":480,"runningHint":"Slow lap. Look at green things, not the clock."}},{"id":"s2","title":"Identify three plants","detail":"Book or free ID app is fine.","tip":"Sit once on a stoop or low wall—let plants come to you instead of hunting every verge.","estimateMinutes":20,"interaction":{"kind":"counter","prompt":"Name each plant as you identify it.","count":3,"itemLabel":"plant"}},{"id":"s3","title":"Write their common names down","tip":"Read each name aloud once—your mouth remembers what the thumb forgets.","estimateMinutes":5,"interaction":{"kind":"confirm"}}]'::jsonb, 'outside'),
  ('q-w-07', 'Visit a shop you have never entered', 'Step inside; stay at least 5 minutes.', 'Pick any local store, bakery, or shop you always pass. Go in, browse, and optionally buy one small item or thank the staff and leave.', 'cat-adventure', 'weekly', 'easy', 25, 'What surprised you once you crossed the threshold?', 'text', 'Cross the threshold of a place you always pass.', '[{"id":"s1","title":"Choose a shop you never entered","tip":"Start small—a bakery line often feels gentler than a quiet boutique floor.","estimateMinutes":3,"interaction":{"kind":"input","prompt":"Which shop is it — and what kept you from entering before?","minChars":15,"placeholder":"The tiny lamp store on the corner; it always looked too quiet…"}},{"id":"s2","title":"Stay inside at least 5 minutes","tip":"Notice scent and sound before shelves—those orient you faster than scanning labels.","estimateMinutes":5,"interaction":{"kind":"timer","minSeconds":300,"runningHint":"Inside? Lock the phone. Scent, sound, shelves."}},{"id":"s3","title":"Browse or thank someone and leave","tip":"Thank staff lightly; sometimes they were the best part of the errand.","estimateMinutes":5,"interaction":{"kind":"confirm"}}]'::jsonb, 'weekend'),
  ('q-w-08', 'Drink morning coffee or tea outside', 'First cup of the day on a balcony, stoop, or yard.', 'Prepare your drink as usual. Consume the first cup outdoors (balcony counts). No work email during the cup.', 'cat-relax', 'weekly', 'easy', 15, 'How did outdoor light change the start of your day?', 'photo', 'Start the day outside with your first drink.', '[{"id":"s1","title":"Prepare your drink as usual","tip":"Heat the mug the way you would for a guest—small rituals change taste more than beans.","estimateMinutes":3,"interaction":{"kind":"confirm"}},{"id":"s2","title":"Take the first cup outdoors","detail":"Balcony counts.","tip":"Step out before the first sip; let temperature and air hit your face before flavor.","estimateMinutes":12,"interaction":{"kind":"timer","minSeconds":600,"runningHint":"Sip slowly. Look at something far away."}},{"id":"s3","title":"Skip work email until the cup is empty","tip":"Fix your eyes on one distant thing while the cup empties—depth reads as spaciousness.","estimateMinutes":1,"interaction":{"kind":"confirm"}}]'::jsonb, 'do_now'),
  ('q-w-09', 'Have a 15-minute voice or video call', 'Real-time talk with one person—no voice notes.', 'Schedule or place a spontaneous call. Talk about something concrete (weekend plans, a book, a walk) for at least 15 minutes.', 'cat-social', 'weekly', 'medium', 20, 'What was easier live than in text?', 'none', 'Hear a real voice for fifteen minutes.', '[{"id":"s1","title":"Choose one person to call","tip":"Queue the call like a walk: shoes on, lights softer, notifications already off.","estimateMinutes":2,"interaction":{"kind":"input","prompt":"Who are you calling — and what do you want to ask them?","minChars":15,"placeholder":"Dad — how the garden is doing this year…"}},{"id":"calendar_reminder","title":"Put it on your calendar","detail":"Choose a date/time and set a reminder so it actually happens.","tip":"Pick a specific slot you will defend like a quiet coffee—vague someday rarely ships.","estimateMinutes":2,"action":{"kind":"calendar"}},{"id":"s2","title":"Talk live for at least 15 minutes","detail":"Voice or video.","tip":"Ask one follow-up before sharing your update—they feel heard before advice lands.","estimateMinutes":15,"interaction":{"kind":"timer","minSeconds":900,"runningHint":"Start when the call starts. It counts while you talk."}},{"id":"s3","title":"Stick to something concrete","detail":"Plans, a book, a walk.","tip":"Anchor the ending in something future-shaped—a small plan beats a vague goodbye.","estimateMinutes":1,"interaction":{"kind":"input","prompt":"What concrete thing did you land on — a plan, a book, a walk?","minChars":15,"placeholder":"We are walking the river loop next Saturday…"}}]'::jsonb, 'social'),
  ('q-w-10', 'Pick up five pieces of litter on one walk', 'Bring a bag; dispose of trash properly.', 'On any walk, collect five small pieces of litter wearing gloves or using a bag as a barrier. Recycle if possible; otherwise bin.', 'cat-nature', 'weekly', 'easy', 30, 'Did the place feel different after you left it cleaner?', 'text', 'Leave a short stretch of path cleaner than you found it.', '[{"id":"calendar_reminder","title":"Put it on your calendar","detail":"Choose a date/time and set a reminder so it actually happens.","tip":"Pick a specific slot you will defend like a quiet coffee—vague someday rarely ships.","estimateMinutes":2,"action":{"kind":"calendar"}},{"id":"s1","title":"Bring gloves or a bag","tip":"Tuck an extra bag inside the outer one—dry hands make kinder pickup.","estimateMinutes":2,"interaction":{"kind":"confirm"}},{"id":"s2","title":"Collect five pieces of litter on one walk","tip":"Hunt one color only for a few minutes—white or silver catches plastic fastest.","estimateMinutes":25,"interaction":{"kind":"counter","prompt":"Log each piece as you pick it up.","count":5,"itemLabel":"piece"}},{"id":"s3","title":"Dispose or recycle properly","tip":"Separate sharp from soft before the bin—future-you at the curb appreciates it.","estimateMinutes":3,"interaction":{"kind":"photo","prompt":"Snap the haul before it goes in the bin — proof of a cleaner path."}}]'::jsonb, 'outside'),
  ('q-m-01', 'Hike or walk a marked trail you have not done', 'Use an official trail; follow posted signs.', 'Choose a trail or signed path at least 3 km total (or 45 minutes). Bring water. Stop once to read the map or a sign aloud.', 'cat-nature', 'monthly', 'medium', 120, 'Where on the trail did you feel most away from routine?', 'photo', 'Follow a signed trail you have not walked before.', '[{"id":"s1","title":"Pick a marked trail ≥3 km or ~45 min","tip":"Skim reviews for shade and water notes—heat shows up around mile two, not at the trailhead.","estimateMinutes":10,"interaction":{"kind":"input","prompt":"Which trail did you pick — and roughly how long is it?","minChars":10,"placeholder":"The ridge loop above the dam, about 5 km…"}},{"id":"calendar_reminder","title":"Put it on your calendar","detail":"Choose a date/time and set a reminder so it actually happens.","tip":"Pick a specific slot you will defend like a quiet coffee—vague someday rarely ships.","estimateMinutes":2,"action":{"kind":"calendar"}},{"id":"s2","title":"Bring water and follow posted signs","tip":"Pause at forks even when blazes look obvious—maps read clearer standing still.","estimateMinutes":45,"interaction":{"kind":"timer","minSeconds":2700,"runningHint":"Start at the trailhead, lock the phone, walk. It counts on its own."}},{"id":"s3","title":"Pause once to read a map or sign aloud","tip":"Read a sign aloud once—trail grammar sticks when your mouth learns the words.","estimateMinutes":5,"interaction":{"kind":"photo","prompt":"A photo from the trail — the sign, the view, or your boots."}}]'::jsonb, 'outside'),
  ('q-m-02', 'Host or attend one in-person gathering', 'At least three people including you; not a work meeting.', 'Coffee, potluck, board games, or a walk with friends counts. Aim for 60+ minutes together. Phones away except for photos.', 'cat-social', 'monthly', 'hard', 90, 'What would you repeat next month?', 'photo', 'Real faces, real time—at least three people.', '[{"id":"s1","title":"Plan a simple in-person gathering","tip":"Choose food everyone can pick at with hands—shared bowls lower hosting pressure.","estimateMinutes":30,"interaction":{"kind":"input","prompt":"Who is coming — and what simple food will be on the table?","minChars":20,"placeholder":"Jana, Tomáš, and the neighbors; bread, cheese, olives…"}},{"id":"calendar_reminder","title":"Put it on your calendar","detail":"Choose a date/time and set a reminder so it actually happens.","tip":"Pick a specific slot you will defend like a quiet coffee—vague someday rarely ships.","estimateMinutes":2,"action":{"kind":"calendar"}},{"id":"s2","title":"Spend 60+ minutes together","detail":"Phones away except photos.","tip":"Halfway, toast to nothing formal—eye contact and one sentence about the table counts.","estimateMinutes":60,"interaction":{"kind":"timer","minSeconds":3600,"runningHint":"Start it, put the phone away. It counts while you are present."}},{"id":"s3","title":"Say what you would repeat next month","tip":"Ask what felt surprisingly easy—that flags repeats without planning theater.","estimateMinutes":5,"interaction":{"kind":"input","prompt":"What would you repeat next month?","minChars":15,"placeholder":"The no-agenda part — people stayed longer than planned…"}}]'::jsonb, 'social'),
  ('q-m-03', 'Try a new cuisine at a sit-down restaurant', 'Order two dishes you have never tried from that tradition.', 'Pick a cuisine that is new to you (Ethiopian, regional Chinese, etc.). Eat in or proper takeout with time to taste—not desk lunch.', 'cat-adventure', 'monthly', 'medium', 90, 'Which flavor or texture will you remember?', 'photo', 'Taste a cuisine that is new to you.', '[{"id":"s1","title":"Choose a restaurant or cuisine you have not tried","tip":"Let staff pick one plate—trust lowers menu fatigue faster than scrolling photos.","estimateMinutes":15,"interaction":{"kind":"input","prompt":"Which cuisine — and where are you going?","minChars":10,"placeholder":"Georgian — the little place behind the market…"}},{"id":"calendar_reminder","title":"Put it on your calendar","detail":"Choose a date/time and set a reminder so it actually happens.","tip":"Pick a specific slot you will defend like a quiet coffee—vague someday rarely ships.","estimateMinutes":2,"action":{"kind":"calendar"}},{"id":"s2","title":"Order two unfamiliar dishes","tip":"Taste sauces alone first—layers separate like tracks if you listen once cleanly.","estimateMinutes":5,"interaction":{"kind":"counter","prompt":"Name each dish you ordered.","count":2,"itemLabel":"dish"}},{"id":"s3","title":"Eat with attention—not desk lunch","tip":"Phone in the bag, screen down—attention is the rarest seasoning.","estimateMinutes":45,"interaction":{"kind":"photo","prompt":"One photo of the table before you start — then the phone goes away."}}]'::jsonb, 'weekend'),
  ('q-m-05', 'Volunteer one shift of 2+ hours', 'Sign up with an organization; show up on time.', 'Food bank, park cleanup, animal shelter, or community fridge. Complete one scheduled session of at least two hours.', 'cat-social', 'monthly', 'hard', 150, 'What task did you not expect to do?', 'text', 'Show up for your community for two hours.', '[{"id":"s1","title":"Book a slot with an organization","tip":"Arrive ten minutes early to read their bulletin wall—context steadies nerves.","estimateMinutes":30,"interaction":{"kind":"input","prompt":"Which organization — and when is your shift?","minChars":10,"placeholder":"The food bank, Saturday morning…"}},{"id":"calendar_reminder","title":"Put it on your calendar","detail":"Choose a date/time and set a reminder so it actually happens.","tip":"Pick a specific slot you will defend like a quiet coffee—vague someday rarely ships.","estimateMinutes":2,"action":{"kind":"calendar"}},{"id":"s2","title":"Arrive on time and complete the shift","tip":"Introduce yourself twice—to peers and organizers; small repeats build trust fast.","estimateMinutes":120,"interaction":{"kind":"timer","minSeconds":7200,"runningHint":"Start when the shift starts. Lock the phone and be there."}},{"id":"s3","title":"Name one task you did not expect","tip":"Note muscle tiredness, not moral score—bodies measure service more honestly than pride.","estimateMinutes":5,"interaction":{"kind":"input","prompt":"What task did you not expect to be doing?","minChars":20,"placeholder":"Sorting donated shoes by size for an hour…"}}]'::jsonb, 'social'),
  ('q-m-06', 'Sleep outside your home one night', 'Camping, cabin, or trusted friend’s guest room counts.', 'Spend one full night away from your usual bed—tent, hostel, or overnight train in a sleeper berth counts if booked in advance.', 'cat-adventure', 'monthly', 'hard', 720, 'What felt different when you woke up?', 'photo', 'Sleep somewhere that is not your usual bed.', '[{"id":"s1","title":"Book or arrange one night away","tip":"Pack one familiar pillowcase—strange beds soften when scent stays partly yours.","estimateMinutes":60,"interaction":{"kind":"confirm"}},{"id":"calendar_reminder","title":"Put it on your calendar","detail":"Choose a date/time and set a reminder so it actually happens.","tip":"Pick a specific slot you will defend like a quiet coffee—vague someday rarely ships.","estimateMinutes":2,"action":{"kind":"calendar"}},{"id":"s2","title":"Spend the full night there","tip":"Open curtains before screens—foreign morning light resets the mind’s jetlag.","estimateMinutes":480,"interaction":{"kind":"photo","prompt":"A photo from where you woke up — the view, the room, the light."}},{"id":"s3","title":"Notice how waking up felt different","tip":"Voice-note one sentence before coffee—groggy honesty ages into a good story later.","estimateMinutes":10,"interaction":{"kind":"input","prompt":"How did waking up feel different?","minChars":20,"placeholder":"Quieter — no traffic, just birds and unfamiliar curtains…"}}]'::jsonb, 'weekend'),
  ('q-y-01', 'Take a trip at least 100 km from home', 'Stay overnight; plan transport and lodging ahead.', 'Travel by any mode to a place at least 100 km away, stay at least one night, and do one activity there you cannot do at home.', 'cat-adventure', 'yearly', 'hard', 2880, 'What from the trip do you want to keep in daily life?', 'photo', 'A short trip that breaks your everyday radius.', '[{"id":"s1","title":"Plan transport and one night away","detail":"≥100 km from home.","tip":"Sketch one loose route on paper—spatial memory likes ink more than GPS tiles.","estimateMinutes":120,"interaction":{"kind":"input","prompt":"Where are you headed — and how are you getting there?","minChars":15,"placeholder":"Train to the mountains, one night in a pension…"}},{"id":"calendar_reminder","title":"Put it on your calendar","detail":"Choose a date/time and set a reminder so it actually happens.","tip":"Pick a specific slot you will defend like a quiet coffee—vague someday rarely ships.","estimateMinutes":2,"action":{"kind":"calendar"}},{"id":"s2","title":"Do one activity you cannot do at home","tip":"Pick one slow ritual locals repeat—belonging souvenirs often come from repetition.","estimateMinutes":180,"interaction":{"kind":"photo","prompt":"Capture the moment you cannot have at home."}},{"id":"s3","title":"Bring back one detail you want to keep","tip":"Pocket a pebble, ticket stub, or leaf—physical reminders age better than camera rolls alone.","estimateMinutes":15,"interaction":{"kind":"input","prompt":"What detail are you keeping — an object, an image, a taste?","minChars":15,"placeholder":"A flat river stone and the smell of pine at dusk…"}}]'::jsonb, 'weekend'),
  ('q-y-02', 'Learn one outdoor skill in a class or with a guide', 'Examples: climbing intro, kayaking, navigation, foraging.', 'Book a single session with an instructor or guided group. Show up prepared per their list and complete the session.', 'cat-nature', 'yearly', 'hard', 240, 'Would you do it again without the instructor?', 'photo', 'Learn an outdoor skill with a real guide.', '[{"id":"s1","title":"Book a session with an instructor","tip":"Skim reviews for kindness toward beginners—confidence transfers from how they teach.","estimateMinutes":60,"interaction":{"kind":"input","prompt":"What skill — and who is teaching you?","minChars":10,"placeholder":"Intro to climbing at the local wall…"}},{"id":"calendar_reminder","title":"Put it on your calendar","detail":"Choose a date/time and set a reminder so it actually happens.","tip":"Pick a specific slot you will defend like a quiet coffee—vague someday rarely ships.","estimateMinutes":2,"action":{"kind":"calendar"}},{"id":"s2","title":"Show up with their prep list","tip":"Dress slightly under your ego—layers you can add beat shivering in stiff new shells.","estimateMinutes":30,"interaction":{"kind":"confirm"}},{"id":"s3","title":"Finish the session and debrief yourself","tip":"Debrief aloud walking to the car—motor memory locks reflections better than couch scrolling.","estimateMinutes":240,"interaction":{"kind":"input","prompt":"What can you do now that you could not before the session?","minChars":25,"placeholder":"Tie a figure-eight knot and trust the rope on an overhang…"}}]'::jsonb, 'outside'),
  ('q-y-03', 'Reconnect with someone you lost touch with for a year+', 'In-person meet preferred; otherwise video call 45+ min.', 'Reach out, explain you want to catch up, and meet or call for at least 45 minutes. Listen more than you talk for the first half.', 'cat-social', 'yearly', 'hard', 60, 'What felt restored—or honestly closed?', 'none', 'Reconnect after a long silence.', '[{"id":"calendar_reminder","title":"Put it on your calendar","detail":"Choose a date/time and set a reminder so it actually happens.","tip":"Pick a specific slot you will defend like a quiet coffee—vague someday rarely ships.","estimateMinutes":2,"action":{"kind":"calendar"}},{"id":"s1","title":"Reach out and propose a real catch-up","tip":"Open with logistics first—schedule sand settles people before hearts unload.","estimateMinutes":30,"interaction":{"kind":"confirm"}},{"id":"s2","title":"Meet or video call ≥45 minutes","tip":"Silence your own story until halfway—lateness in listening reads as love.","estimateMinutes":45,"interaction":{"kind":"timer","minSeconds":2700,"runningHint":"Start when you meet. Be with them, not with the clock."}},{"id":"s3","title":"Listen for the first half of the time","tip":"Name one thing you appreciated aloud—closure likes spoken gratitude.","estimateMinutes":1,"interaction":{"kind":"input","prompt":"What did you learn about them by listening first?","minChars":20,"placeholder":"They changed jobs and never told anyone how scary it was…"}}]'::jsonb, 'social'),
  ('q-y-04', 'Do a full day with no work or chores', 'One waking day: no email, errands, or house projects.', 'Pick a weekend or holiday. No paid work, no cleaning marathons, no “quick” fixes. Spend the day on rest, play, or people.', 'cat-relax', 'yearly', 'medium', 960, 'What did your body do when nothing was “productive”?', 'text', 'One full day without productivity theater.', '[{"id":"s1","title":"Pick a weekend or holiday day","tip":"Declare the day aloud to an empty room—houseplants count as witness if roommates are out.","estimateMinutes":5,"interaction":{"kind":"confirm"}},{"id":"calendar_reminder","title":"Put it on your calendar","detail":"Choose a date/time and set a reminder so it actually happens.","tip":"Pick a specific slot you will defend like a quiet coffee—vague someday rarely ships.","estimateMinutes":2,"action":{"kind":"calendar"}},{"id":"s2","title":"No paid work, errands, or chores marathons","tip":"Eat one meal very slowly—chewing pace drags time back into weekday scale.","estimateMinutes":480,"interaction":{"kind":"confirm"}},{"id":"s3","title":"Spend the day on rest, play, or people","tip":"A nap on the agenda counts—rest is an activity here, not stolen time.","estimateMinutes":480,"interaction":{"kind":"input","prompt":"What did the day hold? What did your body do when nothing was productive?","minChars":30,"placeholder":"Slept in, long lunch, a walk with no destination. My shoulders dropped…"}}]'::jsonb, 'weekend'),
  ('q-w-11', 'Eat one meal outside, whatever the weather', 'A step, a bench, a wall — anywhere with sky above it.', 'Take one meal you were going to eat anyway and eat it outdoors. A doorstep counts. Rain counts. Bring the coat instead of changing the plan.', 'cat-nature', 'weekly', 'easy', 30, 'What did you notice that the kitchen table never shows you?', 'photo', 'The same meal, with weather in it.', '[{"id":"s1","title":"Pick the meal and grab it to go","detail":"Breakfast, lunch, whatever was already happening.","tip":"Do not upgrade the food. The point is the location, not the menu.","estimateMinutes":5,"interaction":{"kind":"confirm"}},{"id":"calendar_reminder","title":"Put it on your calendar","detail":"Choose a date/time and set a reminder so it actually happens.","tip":"Pick a specific slot you will defend like a quiet coffee—vague someday rarely ships.","estimateMinutes":2,"action":{"kind":"calendar"}},{"id":"s2","title":"Find somewhere outside to sit","detail":"A step, a low wall, a bench, the edge of a planter.","tip":"Closer than you think is fine — this is not a picnic expedition.","estimateMinutes":5,"interaction":{"kind":"confirm"}},{"id":"s3","title":"Eat there, without hurrying","detail":"Stay until the food is gone.","estimateMinutes":15,"interaction":{"kind":"timer","minSeconds":600,"runningHint":"Put the phone down — the timer runs on its own."},"tip":"Go gently—notice one small real-world detail before you mark the step done."},{"id":"s4","title":"Take one photo of the view from where you sat","estimateMinutes":1,"interaction":{"kind":"photo","prompt":"Whatever you were looking at while you ate."},"tip":"Go gently—notice one small real-world detail before you mark the step done."}]'::jsonb, 'outside'),
  ('q-w-12', 'Find the oldest tree on your street', 'Look up. Decide which one was here first.', 'Walk your street and pick the tree that has been there longest — thickest trunk, highest crown, most stubborn roots in the pavement. You do not need to be right, only to look properly.', 'cat-nature', 'weekly', 'medium', 30, 'How long had you walked past it without seeing it?', 'photo', 'Every street has one that was here first.', '[{"id":"calendar_reminder","title":"Put it on your calendar","detail":"Choose a date/time and set a reminder so it actually happens.","tip":"Pick a specific slot you will defend like a quiet coffee—vague someday rarely ships.","estimateMinutes":2,"action":{"kind":"calendar"}},{"id":"s1","title":"Walk your street looking up","detail":"The whole length of it, at least once.","tip":"Trunk width tells you more than height — a tall thin tree is usually younger than a fat short one.","estimateMinutes":15,"interaction":{"kind":"confirm"}},{"id":"s2","title":"Pick the one you think is oldest","detail":"Commit to a single tree.","tip":"Look for roots lifting the pavement, bark that has gone deeply grooved, or a crown wider than the ones beside it.","estimateMinutes":5,"interaction":{"kind":"photo","prompt":"Photograph your candidate."}},{"id":"s3","title":"Say why you picked it","estimateMinutes":3,"interaction":{"kind":"input","prompt":"What made you choose that one?","placeholder":"Trunk twice as thick as the rest, and the pavement has given up around it…"},"tip":"Go gently—notice one small real-world detail before you mark the step done."}]'::jsonb, 'outside'),
  ('q-m-07', 'Watch the sun come up somewhere outdoors', 'Be in place before the light is.', 'Pick somewhere with an open view — a hill, a field, a bridge, a long street facing east — and be there before the sun clears the horizon. Stay until it is fully up.', 'cat-nature', 'monthly', 'medium', 90, 'What was the place like before the light reached it?', 'photo', 'Being somewhere before the light gets there.', '[{"id":"calendar_reminder","title":"Put it on your calendar","detail":"Choose a date/time and set a reminder so it actually happens.","tip":"Pick a specific slot you will defend like a quiet coffee—vague someday rarely ships.","estimateMinutes":2,"action":{"kind":"calendar"}},{"id":"s1","title":"Look up when the sun rises tomorrow","detail":"Then decide where you need to be, and when to leave.","tip":"Aim to be in place twenty minutes early — the sky does most of its work before the sun appears.","estimateMinutes":5,"interaction":{"kind":"input","prompt":"Where are you going, and what time do you need to leave?","placeholder":"The hill behind the allotments, out the door by 05:40…"}},{"id":"s2","title":"Get there in the dark","detail":"Somewhere with an open view to the east.","tip":"Take a warm layer more than you think you need. Standing still at dawn is colder than walking at midnight.","estimateMinutes":30,"interaction":{"kind":"confirm"}},{"id":"s3","title":"Stay until the sun is fully up","detail":"Not just the first edge — all of it.","estimateMinutes":30,"interaction":{"kind":"timer","minSeconds":1200,"runningHint":"Watch the colour change. The timer keeps counting."},"tip":"Go gently—notice one small real-world detail before you mark the step done."},{"id":"s4","title":"Photograph it once the light has arrived","estimateMinutes":1,"interaction":{"kind":"photo","prompt":"The view, with the sun in it."},"tip":"Go gently—notice one small real-world detail before you mark the step done."}]'::jsonb, 'weekend'),
  ('q-m-08', 'Walk a river from one bridge to the next', 'Follow moving water instead of a route.', 'Find a river, canal or stream and walk its bank from one crossing to the next. Let the water decide the direction — you are following it, not navigating.', 'cat-nature', 'monthly', 'medium', 120, 'What was on the bank that you would never have driven past?', 'photo', 'Let the water pick the route.', '[{"id":"calendar_reminder","title":"Put it on your calendar","detail":"Choose a date/time and set a reminder so it actually happens.","tip":"Pick a specific slot you will defend like a quiet coffee—vague someday rarely ships.","estimateMinutes":2,"action":{"kind":"calendar"}},{"id":"s1","title":"Find water and a bridge to start from","detail":"A river, canal, or stream — anything with a bank you can walk.","tip":"Map apps show blue lines clearly. Pick a crossing you have driven over but never stood on.","estimateMinutes":15,"interaction":{"kind":"confirm"}},{"id":"s2","title":"Walk the bank to the next crossing","detail":"Follow the water, not a planned route.","tip":"If the bank runs out, cross and carry on the other side — that counts.","estimateMinutes":75,"interaction":{"kind":"timer","minSeconds":2400,"runningHint":"Keep the water on one side. The timer runs on its own."}},{"id":"s3","title":"Photograph the bridge you finished at","estimateMinutes":1,"interaction":{"kind":"photo","prompt":"Where the walk ended."},"tip":"Go gently—notice one small real-world detail before you mark the step done."},{"id":"s4","title":"Note one thing on the bank you would have missed","estimateMinutes":3,"interaction":{"kind":"input","prompt":"What was down there that you never see from the road?","placeholder":"A heron that let me get closer than it should have…"},"tip":"Go gently—notice one small real-world detail before you mark the step done."}]'::jsonb, 'outside'),
  ('q-y-05', 'Spend a night somewhere with no street lights', 'Far enough out that the sky actually has stars in it.', 'Get far enough from a town that the sky goes properly dark — a cabin, a campsite, a friend’s place in the middle of nowhere. Go outside after dark and stay out long enough for your eyes to adjust.', 'cat-nature', 'yearly', 'hard', 720, 'How long did it take before you could see more than you expected?', 'text', 'Somewhere the sky still gets properly dark.', '[{"id":"calendar_reminder","title":"Put it on your calendar","detail":"Choose a date/time and set a reminder so it actually happens.","tip":"Pick a specific slot you will defend like a quiet coffee—vague someday rarely ships.","estimateMinutes":2,"action":{"kind":"calendar"}},{"id":"s1","title":"Find somewhere far enough from town","detail":"A cabin, a campsite, a friend’s place out in the nowhere.","tip":"Light-pollution maps make this easy — you usually need less distance than you would guess.","estimateMinutes":30,"interaction":{"kind":"input","prompt":"Where are you going, and when?","placeholder":"The cottage in October, once the clocks change…"}},{"id":"s2","title":"Get there and stay the night","estimateMinutes":600,"interaction":{"kind":"confirm"},"tip":"Go gently—notice one small real-world detail before you mark the step done."},{"id":"s3","title":"Go outside after dark and let your eyes adjust","detail":"Twenty minutes with no torch and no screen.","tip":"The first five minutes look like nothing. Stay past that — it keeps arriving.","estimateMinutes":20,"interaction":{"kind":"timer","minSeconds":900,"runningHint":"Let your eyes do the work. Keep the screen face down."}},{"id":"s4","title":"Write down what you could see by the end","estimateMinutes":5,"interaction":{"kind":"input","prompt":"What was visible once your eyes had adjusted?","placeholder":"The Milky Way, faintly. And the outline of the hills I could not see at all at first…"},"tip":"Go gently—notice one small real-world detail before you mark the step done."}]'::jsonb, 'weekend'),
  ('q-w-13', 'Get off two stops early and walk the rest', 'Same journey, different last mile.', 'On a trip you were making anyway, get off two stops before yours and walk. Take whichever way looks more interesting rather than the shortest.', 'cat-adventure', 'weekly', 'easy', 35, 'What was on that stretch you had only ever seen through a window?', 'photo', 'The last mile, on foot, for once.', '[{"id":"calendar_reminder","title":"Put it on your calendar","detail":"Choose a date/time and set a reminder so it actually happens.","tip":"Pick a specific slot you will defend like a quiet coffee—vague someday rarely ships.","estimateMinutes":2,"action":{"kind":"calendar"}},{"id":"s1","title":"Get off two stops before yours","detail":"On a journey you were making anyway.","tip":"Decide before you board, or you will talk yourself out of it as the doors open.","estimateMinutes":1,"interaction":{"kind":"confirm"}},{"id":"s2","title":"Walk the rest, the interesting way","detail":"Not the shortest route — the one that looks better.","estimateMinutes":25,"interaction":{"kind":"timer","minSeconds":900,"runningHint":"No need to hurry. The timer keeps counting while you walk."},"tip":"Go gently—notice one small real-world detail before you mark the step done."},{"id":"s3","title":"Photograph one thing you had only seen from the bus","estimateMinutes":1,"interaction":{"kind":"photo","prompt":"Something on the stretch you usually ride past."},"tip":"Go gently—notice one small real-world detail before you mark the step done."}]'::jsonb, 'do_now'),
  ('q-w-14', 'Order the thing you cannot pronounce', 'Point at the menu and find out.', 'In any café, bakery or restaurant, order the item you do not recognise instead of your usual. Ask what it is only after it arrives.', 'cat-adventure', 'weekly', 'easy', 45, 'Was it better or worse than the thing you would have ordered?', 'photo', 'The menu item you always skip.', '[{"id":"calendar_reminder","title":"Put it on your calendar","detail":"Choose a date/time and set a reminder so it actually happens.","tip":"Pick a specific slot you will defend like a quiet coffee—vague someday rarely ships.","estimateMinutes":2,"action":{"kind":"calendar"}},{"id":"s1","title":"Go somewhere with a menu you do not know by heart","detail":"A café, bakery, takeaway, anywhere.","tip":"Somewhere you have walked past a hundred times works better than somewhere new across town.","estimateMinutes":15,"interaction":{"kind":"confirm"}},{"id":"s2","title":"Order the thing you do not recognise","detail":"Do not look it up first.","tip":"If nothing is unfamiliar, order whatever the person before you had.","estimateMinutes":5,"interaction":{"kind":"confirm"}},{"id":"s3","title":"Photograph it before you find out what it is","estimateMinutes":1,"interaction":{"kind":"photo","prompt":"Whatever arrived."},"tip":"Go gently—notice one small real-world detail before you mark the step done."},{"id":"s4","title":"Say what it turned out to be","estimateMinutes":3,"interaction":{"kind":"input","prompt":"What was it, and would you order it again?","placeholder":"Some kind of buckwheat pancake. Better than it looked…"},"tip":"Go gently—notice one small real-world detail before you mark the step done."}]'::jsonb, 'do_now'),
  ('q-w-15', 'Take the first turn you have never taken', 'Leave your door and turn the wrong way on purpose.', 'Walk out and take the first turning you have never been down. Follow it as far as it stays interesting, then find your own way back.', 'cat-adventure', 'weekly', 'easy', 40, 'How close to home was something you had never seen?', 'photo', 'The turning you have walked past for years.', '[{"id":"calendar_reminder","title":"Put it on your calendar","detail":"Choose a date/time and set a reminder so it actually happens.","tip":"Pick a specific slot you will defend like a quiet coffee—vague someday rarely ships.","estimateMinutes":2,"action":{"kind":"calendar"}},{"id":"s1","title":"Leave your door and turn somewhere new","detail":"The first turning you have genuinely never been down.","tip":"It is usually closer than you expect — most people use three routes out of their own street.","estimateMinutes":5,"interaction":{"kind":"confirm"}},{"id":"s2","title":"Follow it while it stays interesting","detail":"Turn again whenever you feel like it.","estimateMinutes":25,"interaction":{"kind":"timer","minSeconds":900,"runningHint":"Wander. The timer runs on its own."},"tip":"Go gently—notice one small real-world detail before you mark the step done."},{"id":"s3","title":"Find your own way back","detail":"Map only if you are properly lost.","estimateMinutes":10,"interaction":{"kind":"photo","prompt":"One thing you found out there."},"tip":"Go gently—notice one small real-world detail before you mark the step done."}]'::jsonb, 'outside'),
  ('q-m-09', 'Swim in a river you had to walk to reach', 'Moving water, trees around it, no car park.', 'Find wild water you have to walk to — a river, a stream pool, a forest lake — and get in. Not a swimming pool and not a beach you can park at. Check the depth and the current before you commit, and take someone with you.', 'cat-adventure', 'monthly', 'hard', 180, 'How long did it take to get in?', 'photo', 'Water you have to walk to.', '[{"id":"calendar_reminder","title":"Put it on your calendar","detail":"Choose a date/time and set a reminder so it actually happens.","tip":"Pick a specific slot you will defend like a quiet coffee—vague someday rarely ships.","estimateMinutes":2,"action":{"kind":"calendar"}},{"id":"s1","title":"Find wild water within reach","detail":"A river, a stream pool, a forest lake — somewhere with no car park.","tip":"Ask locally or check a map for blue lines with footpaths beside them. Swimming spots are usually known.","estimateMinutes":20,"interaction":{"kind":"input","prompt":"Where are you going, and who is coming with you?","placeholder":"The pool below the weir, with Tom, Saturday morning…"}},{"id":"s2","title":"Check it before you get in","detail":"Depth, current, and how you will get out again.","tip":"Cold water takes your breath for the first thirty seconds — that is normal, and it passes. Get in slowly and never alone.","estimateMinutes":10,"interaction":{"kind":"confirm"}},{"id":"s3","title":"Get in","estimateMinutes":15,"interaction":{"kind":"confirm"},"tip":"Go gently—notice one small real-world detail before you mark the step done."},{"id":"s4","title":"Photograph the water once you are out","estimateMinutes":1,"interaction":{"kind":"photo","prompt":"The spot you swam in."},"tip":"Go gently—notice one small real-world detail before you mark the step done."},{"id":"s5","title":"Say how long it took to commit","estimateMinutes":3,"interaction":{"kind":"input","prompt":"How long did it take to get in?","placeholder":"Stood on the rock for about ten minutes talking myself into it…"},"tip":"Go gently—notice one small real-world detail before you mark the step done."}]'::jsonb, 'weekend'),
  ('q-y-06', 'Travel somewhere by a way you have never used', 'Night train, ferry, bike, on foot — anything but your default.', 'Make a real journey using a means of transport you have never taken: a sleeper train, a ferry, a long ride, two days of walking. The destination matters less than how you get there.', 'cat-adventure', 'yearly', 'hard', 1440, 'What did the slower way show you that flying would have skipped?', 'photo', 'The going is the point, not the arriving.', '[{"id":"s1","title":"Pick a way of travelling you have never used","detail":"Sleeper train, ferry, long ride, two days of walking.","tip":"Choose the transport first and the destination second — that is what makes it a different trip rather than the same one, slower.","estimateMinutes":30,"interaction":{"kind":"input","prompt":"How are you travelling, and roughly where to?","placeholder":"Night train to Kraków, because I have never slept on a train…"}},{"id":"calendar_reminder","title":"Put it on your calendar","detail":"Choose a date/time and set a reminder so it actually happens.","tip":"Pick a specific slot you will defend like a quiet coffee—vague someday rarely ships.","estimateMinutes":2,"action":{"kind":"calendar"}},{"id":"s2","title":"Book it","estimateMinutes":20,"interaction":{"kind":"confirm"},"tip":"Go gently—notice one small real-world detail before you mark the step done."},{"id":"s3","title":"Make the journey","estimateMinutes":720,"interaction":{"kind":"confirm"},"tip":"Go gently—notice one small real-world detail before you mark the step done."},{"id":"s4","title":"Photograph something from the way there","detail":"Not the destination — the travelling.","estimateMinutes":1,"interaction":{"kind":"photo","prompt":"Somewhere in the middle of the journey."},"tip":"Go gently—notice one small real-world detail before you mark the step done."}]'::jsonb, 'weekend'),
  ('q-w-16', 'Ask someone how they ended up doing what they do', 'One real question instead of small talk.', 'With anyone you talk to this week — a colleague, a neighbour, someone behind a counter — ask how they got into what they do. Then let them answer properly.', 'cat-social', 'weekly', 'medium', 20, 'What did you learn that you would never have guessed?', 'text', 'One real question instead of the weather.', '[{"id":"s1","title":"Pick who you will ask","detail":"Anyone you will speak to anyway this week.","tip":"It works best with people you see often but know almost nothing about.","estimateMinutes":2,"interaction":{"kind":"confirm"}},{"id":"s2","title":"Ask how they got into it","detail":"Then stop talking.","tip":"The good part usually arrives after the first pause. Let the silence sit rather than filling it.","estimateMinutes":15,"interaction":{"kind":"confirm"}},{"id":"s3","title":"Write down the part you did not expect","estimateMinutes":3,"interaction":{"kind":"input","prompt":"What surprised you about their answer?","placeholder":"Turns out he trained as a vet before any of this…"},"tip":"Go gently—notice one small real-world detail before you mark the step done."}]'::jsonb, 'social'),
  ('q-w-17', 'Eat with someone, phones away', 'One meal, two people, nothing on the table.', 'Share a meal with someone and put both phones somewhere else — a bag, a shelf, another room. Face down on the table does not count.', 'cat-social', 'weekly', 'easy', 60, 'What did you end up talking about?', 'text', 'A meal with nothing else on the table.', '[{"id":"s1","title":"Arrange to eat with someone","detail":"At home or out, cooked or bought.","estimateMinutes":5,"interaction":{"kind":"confirm"},"tip":"Go gently—notice one small real-world detail before you mark the step done."},{"id":"calendar_reminder","title":"Put it on your calendar","detail":"Choose a date/time and set a reminder so it actually happens.","tip":"Pick a specific slot you will defend like a quiet coffee—vague someday rarely ships.","estimateMinutes":2,"action":{"kind":"calendar"}},{"id":"s2","title":"Put both phones somewhere else","detail":"A bag, a shelf, the next room — not face down on the table.","tip":"Say why you are doing it. It lands better than quietly disappearing your phone.","estimateMinutes":1,"interaction":{"kind":"confirm"}},{"id":"s3","title":"Eat, and stay at the table afterwards","estimateMinutes":45,"interaction":{"kind":"timer","minSeconds":1800,"runningHint":"Leave this running and go back to the table."},"tip":"Go gently—notice one small real-world detail before you mark the step done."},{"id":"s4","title":"Note where the conversation went","estimateMinutes":3,"interaction":{"kind":"input","prompt":"What did you end up talking about?","placeholder":"Started with work, ended somewhere near his dad…"},"tip":"Go gently—notice one small real-world detail before you mark the step done."}]'::jsonb, 'social'),
  ('q-w-18', 'Thank someone specifically, out loud', 'Name the actual thing, to their face or on the phone.', 'Pick someone who did something for you and tell them exactly what it was and what it meant. In person or by voice — not a message.', 'cat-social', 'weekly', 'easy', 15, 'How did they react to being told the specific thing?', 'text', 'Say the specific thing, not the general one.', '[{"id":"s1","title":"Pick the person and the exact thing","detail":"Not \"thanks for everything\" — one identifiable act.","tip":"The more specific it is, the harder it is for them to wave it off.","estimateMinutes":3,"interaction":{"kind":"input","prompt":"Who, and what did they do?","placeholder":"Milan — he drove out at eleven at night when the car died…"}},{"id":"s2","title":"Tell them, in person or by voice","detail":"A message does not count for this one.","estimateMinutes":10,"interaction":{"kind":"confirm"},"tip":"Go gently—notice one small real-world detail before you mark the step done."},{"id":"s3","title":"Note how they took it","estimateMinutes":2,"interaction":{"kind":"input","prompt":"How did they react?","placeholder":"Went a bit awkward, then said nobody had mentioned it since…"},"tip":"Go gently—notice one small real-world detail before you mark the step done."}]'::jsonb, 'social'),
  ('q-m-10', 'Invite someone you barely know to do something', 'The person you always say “we should” to.', 'Think of someone you like but have never actually made plans with, and propose something specific with a date attached. A walk, a coffee, a match — anything with a time on it.', 'cat-social', 'monthly', 'hard', 120, 'What made it easier or harder than you expected to ask?', 'text', 'The person you always say "we should" to.', '[{"id":"calendar_reminder","title":"Put it on your calendar","detail":"Choose a date/time and set a reminder so it actually happens.","tip":"Pick a specific slot you will defend like a quiet coffee—vague someday rarely ships.","estimateMinutes":2,"action":{"kind":"calendar"}},{"id":"s1","title":"Name the person and the thing","detail":"Something specific, with a date on it.","tip":"\"Coffee sometime\" gets nowhere. \"Coffee Thursday morning?\" gets an answer either way.","estimateMinutes":5,"interaction":{"kind":"input","prompt":"Who are you asking, and to do what, when?","placeholder":"Petra from the climbing gym — the Saturday market, this weekend…"}},{"id":"s2","title":"Send the invitation","estimateMinutes":5,"interaction":{"kind":"confirm"},"tip":"Go gently—notice one small real-world detail before you mark the step done."},{"id":"s3","title":"Go, if they say yes","detail":"And if they cannot, ask someone else rather than shelving it.","estimateMinutes":90,"interaction":{"kind":"confirm"},"tip":"Go gently—notice one small real-world detail before you mark the step done."},{"id":"s4","title":"Say how the asking felt","estimateMinutes":3,"interaction":{"kind":"input","prompt":"What made it easier or harder than you expected?","placeholder":"Took three goes to send it. She replied in about a minute…"},"tip":"Go gently—notice one small real-world detail before you mark the step done."}]'::jsonb, 'social'),
  ('q-y-07', 'Spend a whole day with someone you usually see for an hour', 'The same person, without the clock.', 'Take someone you normally see in short bursts — a parent, a sibling, an old friend — and spend a full day together. No agenda beyond being there for the length of it.', 'cat-social', 'yearly', 'hard', 480, 'What came up once you were past the first two hours?', 'text', 'The same person, without the clock.', '[{"id":"s1","title":"Pick the person and find the day","detail":"Someone you normally see in short bursts.","tip":"Say it is a whole day up front. Half of what makes it different is them knowing there is no cut-off.","estimateMinutes":15,"interaction":{"kind":"input","prompt":"Who, and when?","placeholder":"Dad, the second Saturday in November…"}},{"id":"calendar_reminder","title":"Put it on your calendar","detail":"Choose a date/time and set a reminder so it actually happens.","tip":"Pick a specific slot you will defend like a quiet coffee—vague someday rarely ships.","estimateMinutes":2,"action":{"kind":"calendar"}},{"id":"s2","title":"Spend the day","detail":"No agenda beyond being there for the length of it.","estimateMinutes":420,"interaction":{"kind":"confirm"},"tip":"Go gently—notice one small real-world detail before you mark the step done."},{"id":"s3","title":"Write down what came up late in the day","detail":"The part that would not have fitted into an hour.","estimateMinutes":5,"interaction":{"kind":"input","prompt":"What came up once you were past the first two hours?","placeholder":"He talked about the year after the divorce. I had never heard any of it…"},"tip":"Go gently—notice one small real-world detail before you mark the step done."}]'::jsonb, 'social'),
  ('q-w-19', 'Read on paper somewhere that is not home', 'A book, a café or a park, thirty minutes.', 'Take something printed — book, magazine, newspaper — somewhere that is not your flat, and read it there for half an hour.', 'cat-relax', 'weekly', 'easy', 40, 'Did reading somewhere else change how much of it stuck?', 'text', 'Paper, and somewhere that is not your flat.', '[{"id":"calendar_reminder","title":"Put it on your calendar","detail":"Choose a date/time and set a reminder so it actually happens.","tip":"Pick a specific slot you will defend like a quiet coffee—vague someday rarely ships.","estimateMinutes":2,"action":{"kind":"calendar"}},{"id":"s1","title":"Take something printed and go out","detail":"Café, park, library, a bench.","tip":"Anything on paper counts — an old magazine off the shelf is fine.","estimateMinutes":10,"interaction":{"kind":"confirm"}},{"id":"s2","title":"Read for half an hour","estimateMinutes":30,"interaction":{"kind":"timer","minSeconds":1500,"runningHint":"Screen down, page open. The timer runs on its own."},"tip":"Go gently—notice one small real-world detail before you mark the step done."},{"id":"s3","title":"Note one thing that stayed with you","estimateMinutes":3,"interaction":{"kind":"input","prompt":"What stuck?","placeholder":"One line about how rivers get their names…"},"tip":"Go gently—notice one small real-world detail before you mark the step done."}]'::jsonb, 'low_energy'),
  ('q-w-20', 'Take the long way home', 'Add fifteen minutes to a journey you make anyway.', 'On a trip home you were making regardless, deliberately take a longer route. No destination, no errand attached — just the extra distance.', 'cat-relax', 'weekly', 'easy', 30, 'What did the extra fifteen minutes give you?', 'text', 'Fifteen minutes you were not going to have.', '[{"id":"s1","title":"On a journey home, pick the longer way","detail":"No errand attached — just the extra distance.","tip":"Decide before you set off. The long way never wins an argument made halfway.","estimateMinutes":2,"interaction":{"kind":"confirm"}},{"id":"calendar_reminder","title":"Put it on your calendar","detail":"Choose a date/time and set a reminder so it actually happens.","tip":"Pick a specific slot you will defend like a quiet coffee—vague someday rarely ships.","estimateMinutes":2,"action":{"kind":"calendar"}},{"id":"s2","title":"Walk it without rushing","estimateMinutes":25,"interaction":{"kind":"timer","minSeconds":900,"runningHint":"No destination but home. The timer keeps counting."},"tip":"Go gently—notice one small real-world detail before you mark the step done."},{"id":"s3","title":"Say what the extra time gave you","estimateMinutes":3,"interaction":{"kind":"input","prompt":"What did the extra fifteen minutes do?","placeholder":"Arrived home already finished with the day instead of bringing it in…"},"tip":"Go gently—notice one small real-world detail before you mark the step done."}]'::jsonb, 'low_energy'),
  ('q-m-11', 'Book two hours at a sauna, bathhouse, or pool', 'Somewhere you can sit in the heat and do nothing useful.', 'Find a public sauna, bathhouse or thermal pool within reach and book two hours. Go with nothing planned for afterwards.', 'cat-relax', 'monthly', 'medium', 150, 'How long before you stopped checking the time?', 'text', 'Heat, water, and nothing useful to do.', '[{"id":"s1","title":"Find somewhere and book two hours","detail":"Public sauna, bathhouse, thermal pool.","tip":"Book a slot rather than planning to drop in — a booking survives a busy week, an intention does not.","estimateMinutes":15,"interaction":{"kind":"input","prompt":"Where, and when?","placeholder":"The old baths on the other side of town, Sunday afternoon…"}},{"id":"calendar_reminder","title":"Put it on your calendar","detail":"Choose a date/time and set a reminder so it actually happens.","tip":"Pick a specific slot you will defend like a quiet coffee—vague someday rarely ships.","estimateMinutes":2,"action":{"kind":"calendar"}},{"id":"s2","title":"Go, with nothing planned afterwards","detail":"The empty hour after is part of it.","estimateMinutes":120,"interaction":{"kind":"confirm"},"tip":"Go gently—notice one small real-world detail before you mark the step done."},{"id":"s3","title":"Note when you stopped checking the time","estimateMinutes":3,"interaction":{"kind":"input","prompt":"How long before you stopped checking the time?","placeholder":"About forty minutes, somewhere in the second round…"},"tip":"Go gently—notice one small real-world detail before you mark the step done."}]'::jsonb, 'weekend'),
  ('q-m-12', 'Take yourself out for a slow breakfast', 'A table, alone, and nowhere to be after.', 'Go out for breakfast on your own with an hour of nothing after it. Bring something to read if you want, but leave the laptop.', 'cat-relax', 'monthly', 'easy', 90, 'What was it like eating somewhere without waiting for anyone?', 'photo', 'A table, alone, and nowhere to be after.', '[{"id":"s1","title":"Pick a morning with nothing after it","detail":"The empty hour afterwards matters as much as the meal.","estimateMinutes":5,"interaction":{"kind":"confirm"},"tip":"Go gently—notice one small real-world detail before you mark the step done."},{"id":"calendar_reminder","title":"Put it on your calendar","detail":"Choose a date/time and set a reminder so it actually happens.","tip":"Pick a specific slot you will defend like a quiet coffee—vague someday rarely ships.","estimateMinutes":2,"action":{"kind":"calendar"}},{"id":"s2","title":"Go out and order properly","detail":"Sit in. Leave the laptop at home.","tip":"Bring something to read if eating alone feels exposed — but try the first ten minutes without it.","estimateMinutes":60,"interaction":{"kind":"timer","minSeconds":2400,"runningHint":"Stay at the table. The timer runs on its own."}},{"id":"s3","title":"Photograph the table","estimateMinutes":1,"interaction":{"kind":"photo","prompt":"What was in front of you."},"tip":"Go gently—notice one small real-world detail before you mark the step done."}]'::jsonb, 'low_energy'),
  ('q-m-13', 'Make something with your hands and give it away', 'Bread, a shelf, a drawing — then hand it over.', 'Make one physical thing from start to finish and give it to someone. It does not need to be good. It needs to be finished and gone.', 'cat-relax', 'monthly', 'medium', 180, 'What was harder — making it, or handing it over?', 'photo', 'Finished, and then gone.', '[{"id":"calendar_reminder","title":"Put it on your calendar","detail":"Choose a date/time and set a reminder so it actually happens.","tip":"Pick a specific slot you will defend like a quiet coffee—vague someday rarely ships.","estimateMinutes":2,"action":{"kind":"calendar"}},{"id":"s1","title":"Decide what you are making and who gets it","detail":"Bread, a shelf, a drawing, a jar of something.","tip":"Choosing the person first makes it much likelier to get finished.","estimateMinutes":10,"interaction":{"kind":"input","prompt":"What are you making, and for whom?","placeholder":"Sourdough for the neighbours who keep taking our parcels in…"}},{"id":"s2","title":"Make it, start to finish","detail":"It does not need to be good.","estimateMinutes":150,"interaction":{"kind":"confirm"},"tip":"Go gently—notice one small real-world detail before you mark the step done."},{"id":"s3","title":"Photograph it before it leaves","estimateMinutes":1,"interaction":{"kind":"photo","prompt":"The finished thing."},"tip":"Go gently—notice one small real-world detail before you mark the step done."},{"id":"s4","title":"Give it away","estimateMinutes":15,"interaction":{"kind":"confirm"},"tip":"Go gently—notice one small real-world detail before you mark the step done."}]'::jsonb, 'weekend'),
  ('q-y-08', 'Go somewhere quiet for a whole weekend', 'Two nights somewhere with less going on than home.', 'Book two nights somewhere quieter than where you live — a village, a cabin, a coast out of season. Arrive with no list of things to see.', 'cat-relax', 'yearly', 'hard', 2880, 'Which day did you actually start to slow down?', 'photo', 'Two nights somewhere with less going on.', '[{"id":"s1","title":"Book two nights somewhere quieter than home","detail":"A village, a cabin, a coast out of season.","tip":"Out of season is the trick — the same place in November costs less and asks less of you.","estimateMinutes":30,"interaction":{"kind":"input","prompt":"Where, and when?","placeholder":"The cottage near the lake, first weekend of March…"}},{"id":"calendar_reminder","title":"Put it on your calendar","detail":"Choose a date/time and set a reminder so it actually happens.","tip":"Pick a specific slot you will defend like a quiet coffee—vague someday rarely ships.","estimateMinutes":2,"action":{"kind":"calendar"}},{"id":"s2","title":"Go without a list of things to see","detail":"Arriving with no plan is the whole exercise.","estimateMinutes":2400,"interaction":{"kind":"confirm"},"tip":"Go gently—notice one small real-world detail before you mark the step done."},{"id":"s3","title":"Photograph the view you kept coming back to","estimateMinutes":1,"interaction":{"kind":"photo","prompt":"Wherever you ended up sitting most."},"tip":"Go gently—notice one small real-world detail before you mark the step done."},{"id":"s4","title":"Note when you actually slowed down","estimateMinutes":5,"interaction":{"kind":"input","prompt":"Which day did you start to slow down?","placeholder":"Not until Sunday morning, honestly…"},"tip":"Go gently—notice one small real-world detail before you mark the step done."}]'::jsonb, 'weekend')
on conflict (id) do update set
  title = excluded.title,
  short_description = excluded.short_description,
  full_description = excluded.full_description,
  category_id = excluded.category_id,
  timeframe = excluded.timeframe,
  difficulty = excluded.difficulty,
  estimated_duration_minutes = excluded.estimated_duration_minutes,
  prompt_for_reflection = excluded.prompt_for_reflection,
  suggested_proof_type = excluded.suggested_proof_type,
  journey_intro = excluded.journey_intro,
  action_steps = excluded.action_steps,
  suggested_group = excluded.suggested_group;
  -- created_at is deliberately not updated: re-running this must not make the
  -- whole catalogue look newly added.

-- Verify.
select
  count(*) as total,
  count(*) filter (where suggested_group is null) as missing_group,
  count(*) filter (where jsonb_array_length(action_steps) = 0) as missing_steps
from public.quests;
